static const uint32_t BLOCK_DIM = 1; // 需要全局softmax，单block执行以简化实现
static const uint32_t DEFAULT_TILE_D = 256; // 沿d_model分块

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    KvCachedAttentionInferenceCustomTilingData tiling;

    // 输入0: q [B, Q, D]
    const gert::Shape* qShape = context->GetInputShape(0);
    const gert::Shape* kShape = context->GetInputShape(1);
    if (qShape == nullptr || kShape == nullptr) {
        return ge::GRAPH_FAILED;
    }

    uint32_t b = static_cast<uint32_t>(qShape->GetOriginShape().GetDim(0));
    uint32_t qLen = static_cast<uint32_t>(qShape->GetOriginShape().GetDim(1));
    uint32_t dModel = static_cast<uint32_t>(qShape->GetOriginShape().GetDim(2));
    uint32_t kvLen = static_cast<uint32_t>(kShape->GetOriginShape().GetDim(1));

    // 简化：面向推理KV缓存场景，推荐B=1, Q=1。此处仍保留通用字段
    context->SetBlockDim(BLOCK_DIM);

    float scale = 1.0f / std::sqrt(static_cast<float>(dModel));

    tiling.set_batch(b);
    tiling.set_qLen(qLen);
    tiling.set_kvLen(kvLen);
    tiling.set_dModel(dModel);
    tiling.set_tileD(DEFAULT_TILE_D);
    tiling.set_scale(scale);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0; // 本示例不申请workspace
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // out shape = q shape
    const gert::Shape* qShape = context->GetInputShape(0);
    gert::Shape* outShape = context->GetOutputShape(0);
    *outShape = *qShape;
    return GRAPH_SUCCESS;
}
static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return ge::GRAPH_SUCCESS;
}
}

